import{_ as n,o as a,c as t,a as s}from"./app.DLPSkIGI.js";const m=JSON.parse('{"title":"Cross-Platform User Isolation Implementation - Proposal","description":"","frontmatter":{},"headers":[],"relativePath":"changes/research-cross-platform-isolation/proposal.md","filePath":"changes/research-cross-platform-isolation/proposal.md","lastUpdated":1771498270000}'),i={name:"changes/research-cross-platform-isolation/proposal.md"};function o(r,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="cross-platform-user-isolation-implementation-proposal" tabindex="-1">Cross-Platform User Isolation Implementation - Proposal <a class="header-anchor" href="#cross-platform-user-isolation-implementation-proposal" aria-label="Permalink to &quot;Cross-Platform User Isolation Implementation - Proposal&quot;">​</a></h1><p>undefined<strong>Date</strong>: 2026-02-18 undefined<strong>Status</strong>: Research Complete → Implementation Planning undefined<strong>Source</strong>: <code>CROSS_PLATFORM_RESEARCH_CONSOLIDATED.md</code></p><hr><h2 id="_1-executive-summary" tabindex="-1">1. Executive Summary <a class="header-anchor" href="#_1-executive-summary" aria-label="Permalink to &quot;1. Executive Summary&quot;">​</a></h2><p>This proposal outlines the implementation strategy for <strong>cross-platform user isolation</strong> in thegent, enabling secure multi-tenant agent execution across macOS, Linux, and Windows.</p><h3 id="_1-1-problem-statement" tabindex="-1">1.1 Problem Statement <a class="header-anchor" href="#_1-1-problem-statement" aria-label="Permalink to &quot;1.1 Problem Statement&quot;">​</a></h3><p>Current thegent architecture lacks tenant-aware isolation mechanisms, creating risk when:</p><ul><li>Multiple agents execute concurrently</li><li>Untrusted agents must be sandboxed</li><li>Production deployments require strong isolation guarantees</li><li>Desktop automation conflicts arise from concurrent UI actions</li></ul><h3 id="_1-2-proposed-solution" tabindex="-1">1.2 Proposed Solution <a class="header-anchor" href="#_1-2-proposed-solution" aria-label="Permalink to &quot;1.2 Proposed Solution&quot;">​</a></h3><p>undefined<strong>Hybrid User Isolation Model</strong>:</p><ul><li>undefined<strong>Default (Development)</strong>: Sub-user isolation (process-level, no permissions required)</li><li>undefined<strong>Opt-in (Production)</strong>: OS user isolation (full OS-level separation, requires admin)</li><li>undefined<strong>Future (Enterprise)</strong>: Container-based isolation (Docker/systemd-nspawn)</li></ul><p>undefined<strong>Multi-Tenant Coordination</strong>:</p><ul><li>File-level: Tenant-aware edit leases</li><li>UI Automation: Desktop automation coordinator with activity detection</li><li>Process: Tenant-aware concurrency limits</li></ul><hr><h2 id="_2-scope-scale" tabindex="-1">2. Scope &amp; Scale <a class="header-anchor" href="#_2-scope-scale" aria-label="Permalink to &quot;2. Scope &amp; Scale&quot;">​</a></h2><h3 id="_2-1-what-s-included" tabindex="-1">2.1 What&#39;s Included <a class="header-anchor" href="#_2-1-what-s-included" aria-label="Permalink to &quot;2.1 What&#39;s Included&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Scope</th><th>Effort</th></tr></thead><tbody><tr><td>undefined<strong>Sub-user Isolation</strong>undefined</td><td>Process-level user context, default mode</td><td>M (Medium)</td></tr><tr><td>undefined<strong>OS User Isolation</strong>undefined</td><td>Full OS user switching (sudoers config), optional</td><td>M</td></tr><tr><td>undefined<strong>Desktop Automation Coordinator</strong>undefined</td><td>Multi-tenant UI action scheduling</td><td>L (Large)</td></tr><tr><td>undefined<strong>Edit Lease Manager</strong>undefined</td><td>Tenant-aware file locks</td><td>S (Small)</td></tr><tr><td>undefined<strong>Concurrency Controller</strong>undefined</td><td>Per-tenant execution limits</td><td>S</td></tr><tr><td>undefined<strong>Cross-Platform Providers</strong>undefined</td><td>macOS/Linux/Windows implementations</td><td>L</td></tr><tr><td>undefined<strong>Security &amp; Compliance</strong>undefined</td><td>Audit logging, capability enforcement</td><td>M</td></tr></tbody></table><h3 id="_2-2-what-s-excluded-future-backlog" tabindex="-1">2.2 What&#39;s Excluded (Future/Backlog) <a class="header-anchor" href="#_2-2-what-s-excluded-future-backlog" aria-label="Permalink to &quot;2.2 What&#39;s Excluded (Future/Backlog)&quot;">​</a></h3><ul><li>Container-based isolation (Phase 13+)</li><li>Network isolation (separate VLAN/namespace)</li><li>Encrypted inter-tenant communication channels</li><li>Tenant-aware resource quotas (CPU, memory, disk)</li></ul><hr><h2 id="_3-architecture-decision" tabindex="-1">3. Architecture Decision <a class="header-anchor" href="#_3-architecture-decision" aria-label="Permalink to &quot;3. Architecture Decision&quot;">​</a></h2><h3 id="_3-1-user-isolation-hybrid-model" tabindex="-1">3.1 User Isolation Hybrid Model <a class="header-anchor" href="#_3-1-user-isolation-hybrid-model" aria-label="Permalink to &quot;3.1 User Isolation Hybrid Model&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│         Thegent Multi-Tenant Architecture        │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                                  │</span></span>
<span class="line"><span>│  ┌────────────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Sub-User Isolation (DEFAULT)              │ │</span></span>
<span class="line"><span>│  │  • Process-level context (uid/gid)         │ │</span></span>
<span class="line"><span>│  │  • No filesystem isolation                 │ │</span></span>
<span class="line"><span>│  │  • No permissions required                 │ │</span></span>
<span class="line"><span>│  │  • ~1ms overhead per action                │ │</span></span>
<span class="line"><span>│  └────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│                                                  │</span></span>
<span class="line"><span>│  ┌────────────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  OS User Isolation (OPT-IN)                │ │</span></span>
<span class="line"><span>│  │  • Full OS-level isolation                 │ │</span></span>
<span class="line"><span>│  │  • Separate home, .config, .local          │ │</span></span>
<span class="line"><span>│  │  • Requires sudoers + doas/sudo config     │ │</span></span>
<span class="line"><span>│  │  • ~50ms overhead per action               │ │</span></span>
<span class="line"><span>│  └────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│                                                  │</span></span>
<span class="line"><span>│  ┌────────────────────────────────────────────┐ │</span></span>
<span class="line"><span>│  │  Docker Isolation (FUTURE - Phase 13+)     │ │</span></span>
<span class="line"><span>│  │  • Container-based full isolation          │ │</span></span>
<span class="line"><span>│  │  • Network namespace included              │ │</span></span>
<span class="line"><span>│  │  • ~500ms overhead per action              │ │</span></span>
<span class="line"><span>│  └────────────────────────────────────────────┘ │</span></span>
<span class="line"><span>│                                                  │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><h3 id="_3-2-coordination-mechanisms" tabindex="-1">3.2 Coordination Mechanisms <a class="header-anchor" href="#_3-2-coordination-mechanisms" aria-label="Permalink to &quot;3.2 Coordination Mechanisms&quot;">​</a></h3><p>undefined<strong>File-Level Coordination</strong>:</p><ul><li>Extend <code>EditLeaseManager</code> with tenant awareness</li><li>File locks: <code>/run/thegent/leases/{tenant_id}/{hash(filepath)}.lock</code></li><li>Conflict resolution: User &gt; Agent (FIFO for agent-agent)</li></ul><p>undefined<strong>UI Automation Coordination</strong>:</p><ul><li>Desktop Automation Coordinator monitors: <ul><li>Current active window (user focus)</li><li>Pending agent actions (queue)</li><li>Desktop resource availability</li></ul></li><li>Scheduling: User actions preempt agents; agents batch by tenant</li></ul><p>undefined<strong>Process Concurrency</strong>:</p><ul><li>Per-tenant concurrency caps (configurable)</li><li>Shared pool for user actions (unlimited priority)</li><li>Escalation queue for backpressure</li></ul><hr><h2 id="_4-key-design-decisions" tabindex="-1">4. Key Design Decisions <a class="header-anchor" href="#_4-key-design-decisions" aria-label="Permalink to &quot;4. Key Design Decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Rationale</th><th>Trade-offs</th></tr></thead><tbody><tr><td>undefined<strong>Sub-user default</strong>undefined</td><td>Fast, zero-permission, suitable for dev</td><td>Less isolation than OS users</td></tr><tr><td>undefined<strong>FIFO for agent conflicts</strong>undefined</td><td>Deterministic, simple, fair</td><td>No priority scheduling</td></tr><tr><td>undefined<strong>Native desktop providers</strong>undefined</td><td>Platform-optimized, no dependencies</td><td>Maintenance burden (3 platforms)</td></tr><tr><td>undefined<strong>Activity detection</strong>undefined</td><td>Detect user focus; prevent agent UI collisions</td><td>Added latency/complexity</td></tr><tr><td>undefined<strong>Hybrid model</strong>undefined</td><td>Balance dev velocity with prod security</td><td>Operational complexity</td></tr></tbody></table><hr><h2 id="_5-success-criteria" tabindex="-1">5. Success Criteria <a class="header-anchor" href="#_5-success-criteria" aria-label="Permalink to &quot;5. Success Criteria&quot;">​</a></h2><h3 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h3><ul><li>[ ] Sub-user isolation configurable via <code>isolation_mode: &quot;sub-user&quot;</code></li><li>[ ] OS user isolation configurable via <code>isolation_mode: &quot;os-user&quot;</code></li><li>[ ] Desktop automation coordinator prevents 95%+ of UI conflicts</li><li>[ ] Edit leases work across all 3 platforms</li><li>[ ] Per-tenant concurrency limits enforced</li></ul><h3 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h3><ul><li>[ ] Isolation overhead: &lt;5ms (sub-user), &lt;100ms (OS user)</li><li>[ ] Edit lease latency: &lt;50ms (p95)</li><li>[ ] Desktop automation decision latency: &lt;200ms (p95)</li><li>[ ] Success rate: &gt;95% for isolated actions</li></ul><h3 id="compliance-security" tabindex="-1">Compliance &amp; Security <a class="header-anchor" href="#compliance-security" aria-label="Permalink to &quot;Compliance &amp; Security&quot;">​</a></h3><ul><li>[ ] Audit log: all tenant isolation events</li><li>[ ] Capability matrix: document per-tenant capabilities</li><li>[ ] Penetration test: attempt cross-tenant data access (fail expected)</li></ul><hr><h2 id="_6-implementation-roadmap" tabindex="-1">6. Implementation Roadmap <a class="header-anchor" href="#_6-implementation-roadmap" aria-label="Permalink to &quot;6. Implementation Roadmap&quot;">​</a></h2><h3 id="phase-1-sub-user-isolation-weeks-1-2" tabindex="-1">Phase 1: Sub-User Isolation (Weeks 1-2) <a class="header-anchor" href="#phase-1-sub-user-isolation-weeks-1-2" aria-label="Permalink to &quot;Phase 1: Sub-User Isolation (Weeks 1-2)&quot;">​</a></h3><ul><li>Implement <code>SubUserIsolationProvider</code></li><li>Extend process execution to set uid/gid context</li><li>Add config: <code>isolation_mode</code>, <code>sub_user_prefix</code></li><li>Tests: 10+ scenarios (file access, env vars, credentials)</li></ul><h3 id="phase-2-edit-lease-manager-enhancement-week-3" tabindex="-1">Phase 2: Edit Lease Manager Enhancement (Week 3) <a class="header-anchor" href="#phase-2-edit-lease-manager-enhancement-week-3" aria-label="Permalink to &quot;Phase 2: Edit Lease Manager Enhancement (Week 3)&quot;">​</a></h3><ul><li>Extend <code>EditLeaseManager</code> with tenant ID tracking</li><li>Implement file lock paths: <code>/run/thegent/leases/{tenant_id}/</code></li><li>Conflict detection &amp; logging</li><li>Tests: 5+ multi-tenant edit scenarios</li></ul><h3 id="phase-3-desktop-automation-coordinator-week-4-5" tabindex="-1">Phase 3: Desktop Automation Coordinator (Week 4-5) <a class="header-anchor" href="#phase-3-desktop-automation-coordinator-week-4-5" aria-label="Permalink to &quot;Phase 3: Desktop Automation Coordinator (Week 4-5)&quot;">​</a></h3><ul><li>Implement <code>DesktopAutomationCoordinator</code></li><li>Platform providers: macOS (AppleScript), Linux (AT-SPI), Windows (UI Automation)</li><li>User activity detection (window focus, active app)</li><li>Action queue &amp; scheduling logic</li><li>Tests: 15+ scenarios (concurrency, preemption, user activity)</li></ul><h3 id="phase-4-os-user-isolation-week-6" tabindex="-1">Phase 4: OS User Isolation (Week 6) <a class="header-anchor" href="#phase-4-os-user-isolation-week-6" aria-label="Permalink to &quot;Phase 4: OS User Isolation (Week 6)&quot;">​</a></h3><ul><li>Implement <code>OSUserIsolationProvider</code></li><li>Sudoers config generator</li><li>Test on macOS (doas), Linux (sudo), Windows (RunAs)</li><li>Tests: 8+ scenarios (permissions, home directory, isolation)</li></ul><h3 id="phase-5-integration-hardening-week-7-8" tabindex="-1">Phase 5: Integration &amp; Hardening (Week 7-8) <a class="header-anchor" href="#phase-5-integration-hardening-week-7-8" aria-label="Permalink to &quot;Phase 5: Integration &amp; Hardening (Week 7-8)&quot;">​</a></h3><ul><li>Wire isolation mode into agent executor</li><li>Concurrency controller integration</li><li>Audit logging, telemetry</li><li>Documentation &amp; troubleshooting</li><li>Performance benchmarking (SLA verification)</li></ul><hr><h2 id="_7-risk-mitigation" tabindex="-1">7. Risk &amp; Mitigation <a class="header-anchor" href="#_7-risk-mitigation" aria-label="Permalink to &quot;7. Risk &amp; Mitigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Impact</th><th>Mitigation</th></tr></thead><tbody><tr><td>undefined<strong>Cross-tenant data leaks</strong>undefined</td><td>Critical</td><td>Penetration tests, audit logging, code review</td></tr><tr><td>undefined<strong>OS user isolation complexity</strong>undefined</td><td>High</td><td>Clear documentation, helper scripts, CI tests</td></tr><tr><td>undefined<strong>Desktop automation flakiness</strong>undefined</td><td>High</td><td>Extensive testing, fallback behaviors, activity detection</td></tr><tr><td>undefined<strong>Performance regression</strong>undefined</td><td>Medium</td><td>Benchmarking, overhead budgets per phase</td></tr><tr><td>undefined<strong>Platform-specific bugs</strong>undefined</td><td>Medium</td><td>Three separate provider implementations, test matrix</td></tr></tbody></table><hr><h2 id="_8-acceptance-criteria" tabindex="-1">8. Acceptance Criteria <a class="header-anchor" href="#_8-acceptance-criteria" aria-label="Permalink to &quot;8. Acceptance Criteria&quot;">​</a></h2><p>undefined<strong>Definition of Done</strong>:</p><ol><li>All phases 1-5 implemented and tested</li><li>All success criteria (functional, non-functional, compliance) met</li><li>Documentation complete (design.md, deployment guide, troubleshooting)</li><li>Performance benchmarks meet SLAs</li><li>Security review passed</li><li>No test regressions in existing codebase</li></ol><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>undefined<strong>Consolidated Research</strong>: <code>docs/research/CROSS_PLATFORM_RESEARCH_CONSOLIDATED.md</code></li><li>undefined<strong>Work Stream Item</strong>: <code>research-cross-platform-isolation</code> (P1, no dependencies)</li><li>undefined<strong>Related Items</strong>: <ul><li><code>research-cross-platform-coordination</code> (depends on this)</li><li><code>research-phase13-tenant-boundary-tests</code> (depends on this)</li></ul></li></ul>`,63)])])}const h=n(i,[["render",o]]);export{m as __pageData,h as default};
